CREATE TABLE metadata_report_cover_references (report_id TEXT NOT NULL REFERENCES metadata_reports(report_id), source_id TEXT NOT NULL, artifact_id TEXT, preview_digest TEXT, preview_variant TEXT, PRIMARY KEY (report_id, source_id), CHECK ((artifact_id IS NULL AND preview_digest IS NULL AND preview_variant IS NULL) OR (length(artifact_id) = 70 AND artifact_id GLOB 'cover_[0-9a-f]*' AND length(preview_digest) = 64 AND preview_digest NOT GLOB '*[^0-9a-f]*' AND preview_variant = 'preview-320x480-rgba-png-v1')));
CREATE TABLE metadata_reports (report_id TEXT PRIMARY KEY NOT NULL CHECK (report_id GLOB 'report_[0-9a-f]*' AND length(report_id) = 71), connection_name TEXT NOT NULL, library_name TEXT NOT NULL, item_id TEXT NOT NULL, file_identity TEXT NOT NULL CHECK (length(file_identity) = 64 AND file_identity NOT GLOB '*[^0-9a-f]*'), content_digest TEXT NOT NULL CHECK (length(content_digest) = 64 AND content_digest NOT GLOB '*[^0-9a-f]*'), schema_version TEXT NOT NULL CHECK (schema_version = 'metadata-report-v49'), document_digest TEXT NOT NULL CHECK (length(document_digest) = 64 AND document_digest NOT GLOB '*[^0-9a-f]*'), document TEXT NOT NULL CHECK (typeof(document) = 'text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 2097152), UNIQUE (connection_name, library_name, item_id, file_identity, document_digest));
